mapper.select:
SELECT menu_id
FROM squad_user.sq_role_menu
WHERE role_id = #{roleId}
  AND stage = #{stage}
ORDER BY menu_id

mapper.update:
UPDATE squad_user.sq_role
SET version          = version + 1,
    last_updater_id  = #{actor},
    last_update_time = CURRENT_TIMESTAMP
WHERE role_id = #{roleId}
  AND version = #{version}
